EP.notes = [
 {title:"Indian Constitution — Basics", subj:"Polity", body:"Adopted 26 Nov 1949, enforced 26 Jan 1950. Longest written constitution in the world. Preamble: Justice, Liberty, Equality, Fraternity. Parts: 22 (originally), Articles: 395 (originally), Schedules: 12. Dr. B.R. Ambedkar chaired the Drafting Committee. Fundamental Rights: Articles 12–35 (Part III). DPSP: Articles 36–51 (Part IV)."},
 {title:"Fundamental Rights (Part III)", subj:"Polity", body:"Right to Equality (14–18), Right to Freedom (19–22), Right against Exploitation (23–24), Right to Freedom of Religion (25–28), Cultural & Educational Rights (29–30), Right to Constitutional Remedies (32). Article 32 — Dr. Ambedkar called it the 'heart and soul' of the Constitution."},
 {title:"Rivers of India — Quick Facts", subj:"Geography", body:"Ganga (2,525 km) — longest river in India; originates at Gangotri (Uttarkashi). Brahmaputra (2,900 km total) — originates in Tibet as Tsangpo. Godavari (1,465 km) — longest peninsular river, 'Dakshin Ganga'. Narmada — flows west into the Arabian Sea. Indus — originates near Mansarovar."},
 {title:"Indian Economy — Key Institutions", subj:"Economy", body:"RBI (1935) — central bank, issues currency, repo rate setter. SEBI (1992) — capital markets regulator. NITI Aayog (2015) — replaced Planning Commission. GST (1 July 2017) — 'One Nation, One Tax'. Fiscal deficit target and FRBM Act are favourite exam topics."},
 {title:"Modern History — Key Dates", subj:"History", body:"1857 — First War of Independence. 1885 — Indian National Congress founded. 1905 — Partition of Bengal. 1919 — Jallianwala Bagh. 1920 — Non-Cooperation Movement. 1930 — Dandi March. 1942 — Quit India Movement. 1947 — Independence (15 August)."},
 {title:"Science — Everyday Facts", subj:"Science", body:"Speed of light: 3×10⁸ m/s. Boiling point of water: 100°C. Human body: 206 bones (adult), 4 heart chambers. Photosynthesis: 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ (in chlorophyll, sunlight). SI units: metre (length), kilogram (mass), second (time), ampere (current), kelvin (temperature)."},
 {title:"Maths Shortcuts — Percentage & Ratio", subj:"Maths", body:"x% of y = y% of x. To find % change: (Change ÷ Original) × 100. Ratio a:b — if a+b given, a = (a/(a+b)) × total. Simple Interest = PRT/100. Speed = Distance ÷ Time; km/h → m/s multiply by 5/18. Average = Sum ÷ Count."},
 {title:"Current Affairs — How to Revise", subj:"Strategy", body:"Daily: 10 CA facts + 1 quiz. Weekly: revise the week's facts (Sunday). Monthly: one-page summary per topic (Polity, Economy, Environment, Science). Always note the SOURCE and DATE of every fact — UPSC/SSC ask 'which/when' questions, not opinions."},
];

